    fun assetFor(text: String): String? = MAP[text.trim()]

    /** Clip count, pinned by the gate test against the content. */
    val size: Int get() = MAP.size

    /** Every bundled asset path (gate test pins their shape). */
    fun assetPaths(): Set<String> = MAP.values.toSet()
}
